-- Demo backup for the live demo (no AI calls needed).
--
-- Anonymous users get a new random id on every phone, so a fixed "demo account" row
-- would be invisible to them under RLS. Instead the demo plan ships with the app
-- (src/mock/plan.json + src/mock/level.json) and is copied into whoever is signed in
-- by the import_plan() function from 001_init.sql:
--
--   App: upload screen → "Try the demo plan"  (calls supabase.rpc('import_plan', ...))
--
-- Stage 1 (SQL) comes with pre-written questions and resources. Stages 2–3 are
-- generated by the generate-level Edge Function the first time they're opened.
--
-- Sunday 9:00 checklist:
--   1. Run 001_init.sql once (SQL editor) if it isn't applied yet.
--   2. Authentication → Sign In / Providers → enable "Allow anonymous sign-ins".
--   3. On the demo phone, tap "Try the demo plan" once to confirm it loads.
--
-- Optional sanity check (run in the SQL editor): count rows per table.
select 'plans' as t, count(*) from public.plans
union all select 'levels', count(*) from public.levels
union all select 'questions', count(*) from public.questions;
